head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.delLowP = 0;
/* ★Wcraft guide★    
스크립트 수작업 유의사항

*/

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 현재 별도 초기화 로직 없음.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 시점 — 현재 별도 해제 로직 없음.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MxDataSet_OnLoadCompleted
 * @description 목록 조회 완료 콜백 — 총건수를 textbox_1 에 표시한다.
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 * @example scwin.MxDataSet_OnLoadCompleted(MxDataSet.getRowCount());
 */
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    try {
        textbox_1.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10201.MxDataSet_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_sys_search_onclick
 * @description 「조회」 버튼 클릭 — 공시접수일자(시작/종료) 입력을 확인한 뒤 목록을 조회한다(listSync).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_sys_search ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_sys_search_onclick = function(e) {
    try {
        if (txb_date1.getValue() !== "" && txb_date2.getValue() !== "") {
            scwin.listSync(); // alert();

        } else {
            alert("일자를 지정하십시요");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10201.btn_sys_search_onclick" });
    }
};

/**
 * @method
 * @name btn_cal_onclick
 * @description 달력 버튼 클릭 — 공시접수일자(시작, txb_date1) 달력 팝업을 연다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_cal ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_cal_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg1, 'txb_date1', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10201.btn_cal_onclick" });
    }
};

/**
 * @method
 * @name image_6_onclick
 * @description 발행회사 검색 버튼 클릭 — 발행회사검색 팝업을 연다(isurcdSearch).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (image_6 ev:onclick 바인딩으로 자동 호출)
 */
scwin.image_6_onclick = function(e) {
    try {
        scwin.isurcdSearch(isur_cd, isur_nm);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10201.image_6_onclick" });
    }
};

/**
 * @method
 * @name image_2_onclick
 * @description 달력 버튼 클릭 — 공시접수일자(종료, txb_date2) 달력 팝업을 연다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (image_2 ev:onclick 바인딩으로 자동 호출)
 */
scwin.image_2_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg2, 'txb_date2', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10201.image_2_onclick" });
    }
};

/**
 * @method
 * @name btn_toExcel_onclick
 * @description 「엑셀다운로드」 버튼 클릭 — 그리드(MxGrid_1) 내용을 엑셀로 다운로드한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_toExcel ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_toExcel_onclick = function(e) {
    try {
        MxGrid_1.GridToExcel("대표이사변경", "", "2");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10201.btn_toExcel_onclick" });
    }
};

/**
 * @method
 * @name MxGrid_1_OnClick
 * @description 그리드 클릭 — 클릭 행 인덱스를 delLowP 에 보관한다(접수번호 조회는 구 로직 잔존).
 * @param {Number} row 클릭한 행 인덱스
 * @param {String} colid 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.MxGrid_1_OnClick(0, "ACPT_NO");
 */
scwin.MxGrid_1_OnClick = function(row, colid) {
    try {
        scwin.delLowP = row;

        const sCd = MxDataSet.getCellData(row, "ACPT_NO");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10201.MxGrid_1_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 대표이사변경 목록(MxDataSet)을 조회(/ceochg.do)하고 완료 후 구 콜백(MxDataSet_OnLoadCompleted)으로 총건수를 갱신한다.
 * @returns {void}
 * @hidden N
 * @example scwin.listSync();
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/ceochg.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_OnLoadCompleted(MxDataSet.getRowCount()); // 구 콜백 연결

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name gform_onload
 * @description 구 gform onload — 대표이사변경 목록(MxDataSet)을 조회한 뒤 일자 기본값(toDaySet)과 발행사 자동완성(fn_com_isur)을 설정한다.
 * @returns {void}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = async function() {
    // PanelToGroupBox_02(panel_2);
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_OnLoadCompleted(MxDataSet.getRowCount()); // 구 콜백 연결

    toDaySet(txb_date1);

    toDaySet(txb_date2);
    await $c.cm.comIsur(isur_cd, isur_nm);
};

/**
 * @method
 * @name isurcdSearch
 * @description 발행회사검색 팝업(ULDCOM00007)을 열고 반환값("발행사코드^발행사명")을 대상 컴포넌트에 반영한다. pcc/stf $c.cm.isurcdSearch 는 팝업이 $c.cm.isurSearchRtn 을 되부르는 콜백 계약이라, 반환값 계약인 본 모듈 팝업과 맞지 않아 화면 로컬로 유지한다.
 * @param {Object} codeComp 발행사코드 컴포넌트(autoComplete)
 * @param {Object} labelComp 발행사명 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 * @example scwin.isurcdSearch(isur_cd, isur_nm);
 */
scwin.isurcdSearch = async function (codeComp, labelComp) {
    const options = { id : "ULDCOM00007", title : "발행회사검색창", type : "pageFramePopup", width : "618px", height : "730px" };
    const result = await $c.win.openPopup("/ui/common/ULDCOM00007.xml", options, {});
    if (result) {
        const [isurCd, comAbbrv] = String(result).split("^");
        codeComp.setValue(isurCd);
        labelComp.setValue(comAbbrv);
    }
};
